#include <stdint.h>
#include "syscall.h"
#include "vfs.h"
#include "scheduler.h"
#include "isr.h"
#include "mm.h"
#include "drivers.h"
#include "kernel.h"
#include "elf.h"
#define USER_STACK_TOP 0x00bff000u
#define EXEC_MAX_IMAGE (256u*1024u)
#define ERR_ENOENT 2
#define ERR_ENOEXEC 8
#define ERR_ENOMEM 12
static pcb_t *exec_pending_process; static uint32_t exec_pending_entry;
static pcb_t *current_process(void){return scheduler_current();} static int user_buf(uint32_t p,uint32_t n,uint32_t write){pcb_t*q=current_process();if(n==0)return p>=0x400000u&&p<0xc0000000u;return q&&vmm_validate_user_ptr(q->address_space,p,n,write)==0;} static int user_string(uint32_t p){pcb_t*q=current_process();if(!q||p<0x400000u||p>=0xc0000000u)return -1;for(uint32_t i=0;i<256u&&p+i<0xc0000000u;i++){if(vmm_validate_user_ptr(q->address_space,p+i,1,0)!=0)return -1;if(((const char*)p)[i]==0)return 0;}return -1;}
static int32_t rd(uint32_t a,uint32_t b,uint32_t c){return user_buf(b,c,1)?vfs_read((int)a,(void*)b,c):-1;} static int32_t wr(uint32_t a,uint32_t b,uint32_t c){return user_buf(b,c,0)?vfs_write((int)a,(const void*)b,c):-1;} static int32_t op(uint32_t a,uint32_t b,uint32_t c){(void)c;return user_string(a)==0?vfs_open((const char*)a,b):-1;} static int32_t cl(uint32_t a,uint32_t b,uint32_t c){(void)b;(void)c;return vfs_close((int)a);} static int32_t fk(uint32_t a,uint32_t b,uint32_t c){(void)a;(void)b;(void)c;return process_fork();} static int32_t ex(uint32_t a,uint32_t b,uint32_t c){(void)b;(void)c;pcb_t*p=scheduler_current();return p?process_exit_with_status(p->pid,(int32_t)a):-1;} static int32_t gp(uint32_t a,uint32_t b,uint32_t c){(void)a;(void)b;(void)c;pcb_t*p=scheduler_current();return p?(int32_t)p->pid:-1;} static int32_t yl(uint32_t a,uint32_t b,uint32_t c){(void)a;(void)b;(void)c;scheduler_yield();return 0;} static int32_t sl(uint32_t a,uint32_t b,uint32_t c){(void)b;(void)c;ksleep_ms(a);return 0;} static int32_t wt(uint32_t a,uint32_t b,uint32_t c){(void)c;int ok=(b==0)||user_buf(b,sizeof(int32_t),1);return ok?process_wait((pid_t)a,b?(int32_t*)b:0):-1;} static int32_t ee(uint32_t a,uint32_t b,uint32_t c){(void)b;(void)c;pcb_t*q=current_process();uint8_t*image;int fd;ssize_t n;uint32_t entry;address_space_t*space;address_space_t*old;if(!q||user_string(a)!=0)return-ERR_ENOENT;fd=vfs_open((const char*)a,0);if(fd<0)return-ERR_ENOENT;image=(uint8_t*)kmalloc(EXEC_MAX_IMAGE);if(!image){vfs_close(fd);return-ERR_ENOMEM;}n=vfs_read(fd,image,EXEC_MAX_IMAGE);vfs_close(fd);if(n<=0||n==(ssize_t)EXEC_MAX_IMAGE){kfree(image);return-ERR_ENOEXEC;}space=vmm_create_address_space();if(!space){kfree(image);return-ERR_ENOMEM;}if(!vmm_user_alloc(space,USER_STACK_TOP-PAGE_SIZE,1,PAGE_WRITE)){vmm_destroy_address_space(space);kfree(image);return-ERR_ENOMEM;}if(elf32_load(image,(uint32_t)n,space,&entry)!=0){vmm_destroy_address_space(space);kfree(image);return-ERR_ENOEXEC;}old=q->address_space;q->address_space=space;q->entry_point=entry;q->user_stack=USER_STACK_TOP;q->user_mode=1;q->cpu_state.eip=entry;q->cpu_state.esp=USER_STACK_TOP;vmm_switch_address_space(space);tss_set_kernel_stack((uint32_t)&q->kernel_stack[4096]);if(old)vmm_destroy_address_space(old);exec_pending_process=q;exec_pending_entry=entry;kfree(image);return 0;} static int32_t mm(uint32_t a,uint32_t b,uint32_t c){pcb_t*q=current_process();uint32_t pages,i,base=a;if(!q||b==0)return-1;if(base==0)base=0x01000000u;if((base&0xfffu)||base<0x400000u||base>=0xc0000000u||b>0xc0000000u-base)return-1;pages=(b+PAGE_SIZE-1u)/PAGE_SIZE;for(i=0;i<pages;i++)if(vmm_get_user_physical(q->address_space,base+i*PAGE_SIZE))return-1;for(i=0;i<pages;i++){uint32_t p=pmm_alloc_page();if(!p){while(i--)vmm_unmap_user(q->address_space,base+i*PAGE_SIZE);return-1;}if(vmm_map_user(q->address_space,base+i*PAGE_SIZE,p,c|PAGE_WRITE)!=0){pmm_free_page(p);while(i--)vmm_unmap_user(q->address_space,base+i*PAGE_SIZE);return-1;}}return(int32_t)base;} static int32_t mu(uint32_t a,uint32_t b,uint32_t c){pcb_t*q=current_process();uint32_t pages,i;(void)c;if(!q||b==0||(a&0xfffu)||a<0x400000u||a>=0xc0000000u||b>0xc0000000u-a)return-1;pages=(b+PAGE_SIZE-1u)/PAGE_SIZE;for(i=0;i<pages;i++)if(!vmm_get_user_physical(q->address_space,a+i*PAGE_SIZE))return-1;for(i=0;i<pages;i++)vmm_unmap_user(q->address_space,a+i*PAGE_SIZE);return 0;} static int32_t un(uint32_t a,uint32_t b,uint32_t c){(void)b;(void)c;const char*s="ceblar-20 0.6.0 x86";uint32_t n=0;while(s[n])n++;if(!user_buf(a,n+1,1))return -1;char*d=(char*)a;for(uint32_t i=0;i<=n;i++)d[i]=s[i];return 0;}
static int32_t(*table[SYS_COUNT])(uint32_t,uint32_t,uint32_t);
void syscall_init(void){table[0]=rd;table[1]=wr;table[2]=op;table[3]=cl;table[4]=fk;table[5]=ex;table[6]=gp;table[7]=yl;table[8]=sl;table[9]=wt;table[10]=ee;table[11]=mm;table[12]=un;table[13]=mu;serial_write("syscall: initialized successfully\n");}
int32_t syscall_dispatch(uint32_t n,uint32_t a,uint32_t b,uint32_t c){return n<SYS_COUNT&&table[n]?table[n](a,b,c):-1;} registers_t*syscall_from_interrupt(registers_t*r){pcb_t*q=scheduler_current();if(r)r->eax=(uint32_t)syscall_dispatch(r->eax,r->ebx,r->ecx,r->edx);if(r&&q==exec_pending_process){r->eip=exec_pending_entry;r->cs=0x1bu;r->eflags=0x202u;r->useresp=USER_STACK_TOP;r->ss=0x23u;exec_pending_process=0;}if(q&&(q->state==PROCESS_BLOCKED||q->state==PROCESS_ZOMBIE))return scheduler_block_current(r);return r;}
